\connect f14_synthetic
-- Canonical-origin fixture adapted exactly like the existing issue85 lab.
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('admin_private.pazo_live_artifact_ready()'::regprocedure);EXECUTE replace(d,'https://pazo-app-t83r.vercel.app','https://pazo-app.vercel.app');END $$;
ALTER TABLE admin_private.pazo_live_release_artifact DROP CONSTRAINT pazo_live_release_artifact_return_origin_check;
UPDATE admin_private.pazo_live_release_artifact SET return_origin='https://pazo-app.vercel.app';
UPDATE admin_private.paypal_gateway_settings SET return_origin='https://pazo-app.vercel.app' WHERE environment='live';
UPDATE admin_private.paypal_gateway_settings s SET client_id_vault=g.client_id_vault,client_secret_vault=g.client_secret_vault FROM admin_private.pazo_paypal_merchant_generations g WHERE s.environment='live' AND g.generation=1;
UPDATE supporter_private.pazo_paypal_live_worker_control SET enabled=true,processing_enabled=true,last_heartbeat_at=clock_timestamp();
UPDATE supporter_private.gradual_incident SET resolved_at=clock_timestamp();
UPDATE supporter_private.pazo_paypal_live_event_inbox SET processing_state='processed' WHERE processing_state='held';
UPDATE supporter_private.public_supporter_control SET webhook_ok_at=clock_timestamp();
-- The kernel paused promotion; its final fixture had re-enabled it for races.
UPDATE supporter_private.public_supporter_control SET invitations_enabled=false;
SELECT f18_test.check('POSTGRES_ONLY_CERTIFICATE',NOT has_function_privilege('authenticated','supporter_private.certify_public_supporter(text,text,text)','EXECUTE') AND NOT has_function_privilege('service_role','supporter_private.certify_public_supporter(text,text,text)','EXECUTE'));
SELECT f18_test.check('CERTIFIED_OPERATOR_EVIDENCE',supporter_private.certify_public_supporter(repeat('a',40),repeat('b',64),repeat('c',64)));
SELECT f18_test.check('HEALTH_REAL_FINANCIAL_GUARDS',supporter_private.public_supporter_health());
SELECT set_config('request.jwt.claims','{"role":"service_role"}',false);
SELECT f18_test.check('EXPLICIT_ADMIN_PUBLIC_OPEN',public.pazo_f18_supporter_admin_action('82000000-0000-4000-8000-00000000ffff','open_checkouts',1,gen_random_uuid())->>'code'='updated');
SELECT f18_test.check('ELIGIBLE_NO_INTEREST_ADMITTED',admin_private.pazo_live_control_admits(f18_test.owner(170),1) AND NOT EXISTS(SELECT 1 FROM supporter_private.gradual_interest WHERE owner_id=f18_test.owner(170)));
SELECT f18_test.check('GIFT_CAN_VOLUNTARILY_SUPPORT',admin_private.pazo_live_control_admits(f18_test.owner(105),1));
SELECT f18_test.check('QA_NOT_ADMITTED',NOT admin_private.pazo_live_control_admits(f18_test.owner(2),1));
SELECT f18_test.check('TERMS_STILL_REQUIRED',public.pazo_f16_live_service_checkout_begin(f18_test.owner(170),gen_random_uuid(),1,'es','wrong',repeat('a',64))->>'code'='published_terms_unverified');
SELECT f18_test.check('FIRST_CHECKOUT_WITHOUT_QUOTA',(SELECT (public.pazo_f16_live_service_checkout_begin(f18_test.owner(170),'18000000-0000-4000-8000-000000000170',1,'es',terms_version,terms_digest)->>'ok')::boolean FROM supporter_private.pazo_live_offer_versions WHERE locale='es'));
SELECT f18_test.check('DIFFERENT_KEY_BLOCKED',(SELECT public.pazo_f16_live_service_checkout_begin(f18_test.owner(170),gen_random_uuid(),1,'es',terms_version,terms_digest)->>'code'='owner_slot_occupied' FROM supporter_private.pazo_live_offer_versions WHERE locale='es'));
SELECT f18_test.check('ONE_OPEN_INTENT',(SELECT count(*)=1 FROM supporter_private.pazo_paypal_live_checkout_intents WHERE owner_id=f18_test.owner(170) AND closed_at IS NULL));
SELECT f18_test.check('PROVIDER_CLAIM_ONCE',public.pazo_f16_live_service_provider_claim_with_origin(f18_test.owner(170),(SELECT intent_id FROM supporter_private.pazo_paypal_live_checkout_intents WHERE owner_id=f18_test.owner(170)),'18000000-0000-4000-8000-000000000170',1,'https://pazo-app.vercel.app'));
SELECT f18_test.check('PROVIDER_RECLAIM_DENIED',NOT public.pazo_f16_live_service_provider_claim_with_origin(f18_test.owner(170),(SELECT intent_id FROM supporter_private.pazo_paypal_live_checkout_intents WHERE owner_id=f18_test.owner(170)),'18000000-0000-4000-8000-000000000170',1,'https://pazo-app.vercel.app'));
SELECT f18_test.check('PROMO_PAUSE_DOES_NOT_PAUSE_MONEY',(SELECT checkouts_enabled AND NOT invitations_enabled FROM supporter_private.public_supporter_control));
SELECT f18_test.check('PAUSE_NEW_CHECKOUTS',public.pazo_f18_supporter_admin_action('82000000-0000-4000-8000-00000000ffff','pause_checkouts',2,gen_random_uuid())->>'code'='updated');
SELECT f18_test.check('NO_NEW_CREATE_DURING_PAUSE',NOT admin_private.pazo_live_control_admits(f18_test.owner(171),1));
SELECT f18_test.check('ORIGINAL_RECOVERY_DURING_PAUSE',supporter_private.gradual_recovery_admits(f18_test.owner(170),1));
SELECT gradual_test.pay(171);
SELECT public.pazo_f18_supporter_tick(true);
SELECT f18_test.check('RECONCILIATION_THANKS_DURING_PAUSE',supporter_private.public_supporter_paid(f18_test.owner(171)) AND EXISTS(SELECT 1 FROM public.notifications WHERE user_id=f18_test.owner(171) AND type='supporter_verified'));
SELECT public.pazo_f18_supporter_tick(true,true);
SELECT f18_test.check('FINANCIAL_INCIDENT_STOPS_ADMISSION',NOT supporter_private.public_supporter_health());
SELECT f18_test.login(65535);
SELECT f18_test.check('ADMIN_OVERVIEW_CONTRACT',public.pazo_admin_public_supporter_status()->>'source'='public_supporter_admin_v1');
SELECT f18_test.check('ADMIN_MEMBER_CONTRACT',public.pazo_admin_supporter_member(f18_test.owner(171))->>'source'='supporter_member_admin_v1');
SELECT f18_test.check('ADMIN_PAYMENTS_CONTRACT',public.pazo_admin_supporter_payments()->>'source'='supporter_payments_admin_v1');
SELECT f18_test.check('REAL_SIGNED_GROSS_NOT_ATTEMPTS',NOT supporter_private.public_supporter_verified_sale('SALE-GRADUAL-104') AND (public.pazo_admin_live_finance_summary()->'payments'->>'verifiedPayments')::integer=4 AND (public.pazo_admin_live_finance_summary()->'payments'->>'heldPayments')::integer=1);
SELECT f18_test.check('ACTIVE_PAID_METRICS_CONSISTENT',public.pazo_admin_live_finance_summary()->'activePaidAccounts'=public.pazo_admin_public_supporter_status()->'activePaid');
SELECT f18_test.login(107);UPDATE public.pets SET is_lost=true WHERE owner_id=f18_test.owner(107);
INSERT INTO supporter_private.supporter_engagement(owner_id,first_use_at,returned_at,meaningful_at) VALUES(f18_test.owner(107),now()-interval '2 days',now(),now());
UPDATE supporter_private.public_supporter_control SET invitations_enabled=true;
SELECT f18_test.check('RESCUE_NO_PROMO',public.pazo_supporter_promotion('claim')->>'show'='false');
SET ROLE authenticated;
DO $$ BEGIN BEGIN PERFORM public.pazo_f18_supporter_tick(true);RAISE EXCEPTION 'FAIL service RPC exposed';EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS F18 AUTHENTICATED_SERVICE_RPC_DENIED';END;BEGIN PERFORM 1 FROM supporter_private.supporter_promotion;RAISE EXCEPTION 'FAIL private table exposed';EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS F18 AUTHENTICATED_PRIVATE_TABLE_DENIED';END;END $$;
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',false);
DO $$ BEGIN BEGIN PERFORM public.pazo_supporter_promotion('claim');RAISE EXCEPTION 'FAIL anonymous';EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS F18 ANONYMOUS_PROMOTION_DENIED';END;END $$;
